<span class="line"><span style="color:#C678DD;">JOIN</span><span style="color:#D19A66;"> sys</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">master_files</span><span style="color:#ABB2BF;"> mf </span><span style="color:#C678DD;">ON</span><span style="color:#D19A66;"> fs</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">database_id</span><span style="color:#56B6C2;"> =</span><span style="color:#D19A66;"> mf</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">database_id</span><span style="color:#C678DD;"> AND</span><span style="color:#D19A66;"> fs</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">file_id</span><span style="color:#56B6C2;"> =</span><span style="color:#D19A66;"> mf</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">file_id</span></span>
